# Generates a speech fixture for the voice quality tests (stage 2.3.2e).
#
# Windows SAPI synthesises a little over ten seconds of speech at 48 kHz,
# 16-bit, mono into target/audio-fixtures/speech_48k.wav. The file is not
# committed: it depends on the installed voices and is regenerated by
# `make test-voice-quality`.
#
# Usage:
#   powershell -NoProfile -ExecutionPolicy Bypass -File tools/audio-fixtures/make-speech.ps1
#   powershell ... -File tools/audio-fixtures/make-speech.ps1 -OutputPath C:\tmp\speech.wav

param(
    [string]$OutputPath = ""
)

$ErrorActionPreference = "Stop"

$repoRoot = (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path
if ([string]::IsNullOrWhiteSpace($OutputPath)) {
    $OutputPath = Join-Path $repoRoot "client\src-tauri\target\audio-fixtures\speech_48k.wav"
}

$directory = Split-Path -Parent $OutputPath
New-Item -ItemType Directory -Force -Path $directory | Out-Null

Add-Type -AssemblyName System.Speech

# About 130 words per minute at the default rate: with rate +1 the sentences
# below are sized for roughly ten seconds. The test only needs continuous
# speech, not an exact duration.
$text = @"
The quick brown fox jumps over the lazy dog. Pack my box with five dozen liquor jugs.
Sphinx of black quartz, judge my vow.
"@

$format = New-Object System.Speech.AudioFormat.SpeechAudioFormatInfo(
    48000,
    [System.Speech.AudioFormat.AudioBitsPerSample]::Sixteen,
    [System.Speech.AudioFormat.AudioChannel]::Mono
)

$synthesizer = New-Object System.Speech.Synthesis.SpeechSynthesizer
try {
    $synthesizer.Rate = 1
    $synthesizer.SetOutputToWaveFile($OutputPath, $format)
    $synthesizer.Speak($text)
}
finally {
    $synthesizer.Dispose()
}

# Walk the RIFF chunks (SAPI writes an 18-byte fmt chunk) and report the
# duration, so a failed or empty synthesis is visible in the make output.
$bytes = [System.IO.File]::ReadAllBytes($OutputPath)
$offset = 12
$dataBytes = 0
while ($offset + 8 -le $bytes.Length) {
    $chunk = [Text.Encoding]::ASCII.GetString($bytes, $offset, 4)
    $size = [BitConverter]::ToUInt32($bytes, $offset + 4)
    if ($chunk -eq "data") {
        $dataBytes = $size
        break
    }
    $offset += 8 + [int]$size
}
$seconds = $dataBytes / (48000 * 2)
Write-Host ("speech fixture: {0} ({1:N1} s, 48 kHz mono)" -f $OutputPath, $seconds)
